import { canonicalize } from "@hypit/hypit/protocol";
import { captionProducers, captionTypes } from "./manifest.js";
import { appendCaptionUse, assertCaptionProgram, assertCaptionStyle } from "./style.js";
import { assertCaptionDocumentIdentity } from "./identity.js";
import { assertCaptionTiming } from "./temporalize.js";
function inline(value, subject) {
    if (value?.kind !== "inline")
        throw new Error(`${subject} must be inline`);
    return value.value;
}
export const captionComponent = {
    producers: [{
            producer: captionProducers.create,
            handler: ({ inputs }) => ({ outputs: { program: { kind: "inline", value: canonicalize({
                            id: inline(inputs.header?.value, "CaptionTrackSpec").id,
                            documentId: inline(inputs.document?.value, "CaptionDocument").id,
                            styles: [], uses: [],
                        }) } }, needs: {} }),
        }, {
            producer: captionProducers.append,
            handler: ({ inputs }) => ({ outputs: { program: { kind: "inline", value: canonicalize(appendCaptionUse(inline(inputs.program?.value, "CaptionProgram"), inline(inputs.filter?.value, "CaptionContentFilter").id, inline(inputs.window?.value, "TemporalWindow"), inline(inputs.style?.value, "CaptionStyle"), inline(inputs.filter?.value, "CaptionContentFilter").role)) } }, needs: {} }),
        }, {
            producer: captionProducers.appendUnbounded,
            handler: ({ inputs }) => ({ outputs: { program: { kind: "inline", value: canonicalize(appendCaptionUse(inline(inputs.program?.value, "CaptionProgram"), inline(inputs.filter?.value, "CaptionContentFilter").id, undefined, inline(inputs.style?.value, "CaptionStyle"), inline(inputs.filter?.value, "CaptionContentFilter").role)) } }, needs: {} }),
        }],
    validators: [
        { type: captionTypes.document, handler: ({ value }) => assertCaptionDocumentIdentity(inline(value, "CaptionDocument")) },
        { type: captionTypes.style, handler: ({ value }) => {
                if (value.kind !== "inline")
                    throw new Error("CaptionStyle must be inline");
                const style = value.value;
                assertCaptionStyle(style);
            } },
        { type: captionTypes.program, handler: ({ value }) => assertCaptionProgram(inline(value, "CaptionProgram")) },
        { type: captionTypes.timing, handler: ({ value }) => assertCaptionTiming(inline(value, "CaptionTiming")) },
    ],
};
